foreach w in a b "c d" e {
  local out "`out'[`w']"
}

clear
input byte id double x float f byte g str12 s
1 1.5 0.1 1 "apple"
2 -2 0.2 1 "Banana split"
3 . 0.3 2 ""
4 0 1 2 "pad"
5 .a . 3 "x"
6 100 2.5 3 "kiwi"
end
foreach v of varlist x-g {
  local out `out' `v'
}
local list "p q r"
foreach w of local list {
  local o2 `o2'`w'
}
foreach n of numlist 1/3 5 {
  local o3 `o3' `n'
}
foreach v of newlist n1 n2 {
  local o4 `o4' `v'
}

local s = 0
forvalues i = 1/10 {
  local s = `s' + `i'
}
forvalues i = 10(-3)1 {
  local d `d' `i'
}
forvalues i = 1 3 to 9 {
  local e `e' `i'
}
forvalues i = 0(0.25)1 {
  local f `f' `i'
}
forvalues i = 5/1 {
  local never `never' `i'
}

local x 5
if `x' < 3 {
  local r low
}
else if `x' < 7 {
  local r mid
}
else {
  local r high
}
if "`r'" == "mid" local ok 1
else local ok 0
if 0 local never 1

foreach a in 1 2 {
  forvalues b = 1/2 {
    local out `out' `a'`b'
  }
}

local a 1
if 1 {
  local b 2
  exit
}
local c 3

* comment line
local a 1 // trailing
local b = 1 + /// continued
   2
